/**
 * Techon ERP — License Gate
 * File: src/licensing/LicenseGate.jsx
 *
 * Wraps the main App component.
 * Shows Activation Screen if trial expired or not activated.
 * Shows Trial Banner if within trial period.
 * Passes through to App when activated.
 *
 * Usage in src/main.tsx (or main.jsx):
 *   import LicenseGate from './licensing/LicenseGate.jsx';
 *   ReactDOM.createRoot(...).render(<LicenseGate />);
 */

