function ThreeDayBanner({ daysLeft, onActivate }) {
  const [dismissed, setDismissed] = useState(false);
  if (dismissed) return null;

  const urgent = daysLeft <= 1;
  return (
    <div style={{
      background   : urgent ? '#fde8ed' : '#e8f4ff',
      borderBottom : '1.5px solid ' + (urgent ? '#f9a8ba' : '#93c5fd'),
      padding      : '7px 20px',
      display      : 'flex',
      alignItems   : 'center',
      justifyContent: 'space-between',
      fontSize     : 12,
      fontFamily   : "'Plus Jakarta Sans', system-ui, sans-serif",
      flexShrink   : 0,
    }}>
      <span style={{ color: urgent ? C.red : '#1e40af', fontWeight: 600 }}>
        {urgent
          ? '⚠️ 3-day demo key expires today! Activate a full license to keep your data.'
          : '🔑 3-day demo key — ' + daysLeft + ' day' + (daysLeft !== 1 ? 's' : '') + ' remaining. Upgrade to a full license anytime.'}
      </span>
      <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
        <button
          onClick={onActivate}
          style={{
            background   : urgent ? C.red : C.blue,
            color        : '#fff',
            border       : 'none',
            borderRadius : 6,
            padding      : '4px 12px',
            fontSize     : 11,
            fontWeight   : 700,
            cursor       : 'pointer',
            fontFamily   : "'Plus Jakarta Sans', system-ui, sans-serif",
          }}
        >
          Upgrade License
        </button>
        <CloseIconButton onClick={function () { setDismissed(true); }} size={28} tone="ghost" />
      </div>
    </div>
  );
}

/* ═══════════════════════════════════════════════════════════════
   CLOCK TAMPERED SCREEN  (all modes)
   Shown when the universal backward-clock check fails.
   ═══════════════════════════════════════════════════════════════ */
/**
 * ClockTamperedScreen
 * Props:
 *   reason      – multi-line string explaining the issue
 *   countdown   – seconds until next auto-check (shown in UI)
 *   checking    – true while a retry is in progress
 *   onRetryNow  – callback to trigger an immediate check
 */
function ClockTamperedScreen({ reason, countdown, checking, onRetryNow, onVerifyOnline, onEnterLicense, verifyError }) {
  return (
    <div style={{
      position       : 'fixed',
      inset          : 0,
      background     : 'linear-gradient(135deg, #0d1b3e 0%, #0f2252 60%, #1a3580 100%)',
      display        : 'flex',
      alignItems     : 'center',
      justifyContent : 'center',
      flexDirection  : 'column',
      fontFamily     : "'Plus Jakarta Sans', system-ui, sans-serif",
    }}>
      {/* Animated clock icon */}
      <div style={{ fontSize: 58, marginBottom: 16, textAlign: 'center',
                    animation: 'tcPulse 2s ease-in-out infinite' }}>🕐</div>

      {/* Card */}
      <div style={{
        background   : '#ffffff',
        borderRadius : 18,
        padding      : '36px 40px',
        maxWidth     : 460,
        width        : '90%',
        boxShadow    : '0 8px 40px rgba(0,0,0,0.3)',
        textAlign    : 'center',
      }}>
        <div style={{ fontSize: 20, fontWeight: 800, color: C.text, marginBottom: 10 }}>
          System Clock Issue Detected
        </div>
        <div style={{ fontSize: 13, color: C.muted, lineHeight: 1.65, marginBottom: 20 }}>
          {reason
            ? reason.split('\n').map(function(line, i) { return <div key={i}>{line}</div>; })
            : 'The system clock appears to have moved backward. Please correct your computer time.'}
        </div>

        {/* Fix steps */}
        <div style={{
          background   : '#fef3e2',
          border       : '1px solid #fcd34d',
          borderRadius : 10,
          padding      : '14px 16px',
          textAlign    : 'left',
          fontSize     : 13,
          color        : '#92400e',
          marginBottom : 20,
        }}>
          <div style={{ fontWeight: 700, marginBottom: 6 }}>How to fix:</div>
          <div style={{ marginBottom: 4 }}>1. Press <strong>Win + I</strong> → Time &amp; Language → Date &amp; Time</div>
          <div style={{ marginBottom: 4 }}>2. Enable <strong>"Set time automatically"</strong></div>
          <div style={{ marginBottom: 4 }}>3. Click <strong>"Sync now"</strong></div>
          <div>4. Click <strong>"Check Now"</strong> below — no restart needed</div>
        </div>

        {/* Auto-retry status + progress bar */}
        <div style={{ marginBottom: 14 }}>
          <div style={{
            fontSize   : 12,
            color      : C.muted,
            marginBottom: 6,
            minHeight  : 18,
            textAlign  : 'center',
          }}>
            {checking
              ? '⏳ Checking license…'
              : countdown !== undefined
                ? 'Auto-checking in ' + countdown + 's'
                : ''}
          </div>
          {/* Progress bar — drains from full to empty over 15 s */}
          <div style={{
            width        : '100%',
            height       : 4,
            background   : '#e2e8f0',
            borderRadius : 4,
            overflow     : 'hidden',
          }}>
            <div style={{
              height     : '100%',
              borderRadius: 4,
              background  : checking
                ? '#94a3b8'
                : 'linear-gradient(90deg, #2979ff, #60a5fa)',
              width      : checking
                ? '100%'
                : (countdown !== undefined ? (countdown / 15 * 100) : 0) + '%',
              transition : 'width 0.9s linear',
            }} />
          </div>
        </div>

        {verifyError ? (
          <div style={{
            fontSize: 12, color: '#b91c1c', marginBottom: 12, textAlign: 'center', lineHeight: 1.5,
            background: '#fef2f2', border: '1px solid #fecaca', borderRadius: 8, padding: '10px 12px',
          }}>{verifyError}</div>
        ) : null}

        {/* Check Now button */}
        <button
          onClick={onRetryNow}
          disabled={checking}
          style={{
            width        : '100%',
            padding      : '12px',
            background   : checking
              ? '#94a3b8'
              : 'linear-gradient(135deg, #2255d4, #2979ff)',
            color        : '#fff',
            border       : 'none',
            borderRadius : 10,
            fontSize     : 14,
            fontWeight   : 700,
            cursor       : checking ? 'not-allowed' : 'pointer',
            transition   : 'background 0.2s',
          }}
        >
          {checking ? 'Checking…' : '✅ Check Now'}
        </button>

        {(onVerifyOnline || onEnterLicense) ? (
          <div style={{ marginTop: 16, paddingTop: 16, borderTop: '1px solid #e2e8f0', textAlign: 'left' }}>
            <div style={{ fontSize: 12, fontWeight: 800, color: C.text, marginBottom: 10, textAlign: 'center' }}>
              Or continue with your license
            </div>
            {onVerifyOnline ? (
              <button
                type="button"
                onClick={onVerifyOnline}
                disabled={checking}
                style={{
                  width: '100%', padding: '11px 12px', marginBottom: 10,
                  background: checking ? '#e2e8f0' : '#f0f9ff',
                  color: checking ? '#94a3b8' : '#0369a1',
                  border: '1.5px solid ' + (checking ? '#cbd5e1' : '#7dd3fc'),
                  borderRadius: 10, fontSize: 13, fontWeight: 700, cursor: checking ? 'not-allowed' : 'pointer',
                  fontFamily: "'Plus Jakarta Sans', system-ui, sans-serif",
                }}
              >
                🔐 Verify license online &amp; continue
              </button>
            ) : null}
            {onEnterLicense ? (
              <button
                type="button"
                onClick={onEnterLicense}
                disabled={checking}
                style={{
                  width: '100%', padding: '11px 12px',
                  background: '#fff', color: '#334155',
                  border: '1.5px solid #cbd5e1', borderRadius: 10, fontSize: 13, fontWeight: 700,
                  cursor: checking ? 'not-allowed' : 'pointer',
                  fontFamily: "'Plus Jakarta Sans', system-ui, sans-serif",
                }}
              >
                🔑 Enter / change license key
              </button>
            ) : null}
            <div style={{ fontSize: 11, color: C.muted, marginTop: 10, lineHeight: 1.5, textAlign: 'center' }}>
              Online verification confirms your license with Techon and updates this device so you are not stuck after fixing the clock or moving PCs.
            </div>
          </div>
        ) : null}
      </div>

      {/* Contact footer */}
      <div style={{ marginTop: 24, display: 'flex', flexWrap: 'wrap', gap: '6px 16px', justifyContent: 'center' }}>
        <a href="mailto:info@techon.lk"
          style={{ color: '#7eb8ff', fontSize: 12, fontWeight: 600, textDecoration: 'none' }}>
          ✉️ info@techon.lk
        </a>
        <span style={{ color: 'rgba(255,255,255,0.25)', fontSize: 12 }}>|</span>
        <span style={{ color: 'rgba(200,220,255,0.85)', fontSize: 12, fontWeight: 500 }}>
          📞 +94 701234678
        </span>
      </div>

      <style>{`@keyframes tcPulse{0%,100%{opacity:1}50%{opacity:0.4}}`}</style>
    </div>
  );
}

/* ═══════════════════════════════════════════════════════════════
   GRACE PERIOD BANNER  (standalone + network-server mode)
   Shown when a paid license is past expiry but within the 3-day
   grace window. Gives shop owners time to renew without lockout.
   ═══════════════════════════════════════════════════════════════ */
function GracePeriodBanner({ graceDaysLeft, onActivate }) {
  const [dismissed, setDismissed] = useState(false);
  if (dismissed) return null;

  const urgent = graceDaysLeft <= 1;
  return (
    <div style={{
      background      : urgent ? '#fde8ed' : '#fef3e2',
      borderBottom    : '2px solid ' + (urgent ? '#f9a8ba' : '#fcd34d'),
      padding         : '8px 20px',
      display         : 'flex',
      alignItems      : 'center',
      justifyContent  : 'space-between',
      fontSize        : 12,
      fontFamily      : "'Plus Jakarta Sans', system-ui, sans-serif",
      flexShrink      : 0,
    }}>
      <span style={{ color: urgent ? C.red : '#92400e', fontWeight: 700 }}>
        {urgent
          ? '⚠️ License expired! Last day of grace period — renew NOW to avoid lockout.'
          : '⏰ License expired. ' + graceDaysLeft + ' grace day' + (graceDaysLeft !== 1 ? 's' : '') + ' remaining. Please renew soon.'}
      </span>
      <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
        <button
          onClick={onActivate}
          style={{
            background   : urgent ? C.red : C.orange,
            color        : '#fff',
            border       : 'none',
            borderRadius : 6,
            padding      : '5px 14px',
            fontSize     : 11,
            fontWeight   : 700,
            cursor       : 'pointer',
            fontFamily   : "'Plus Jakarta Sans', system-ui, sans-serif",
          }}
        >
          Renew License
        </button>
        {!urgent && (
          <CloseIconButton onClick={function () { setDismissed(true); }} size={28} tone="ghost" />
        )}
      </div>
    </div>
  );
}

/* ═══════════════════════════════════════════════════════════════
   CLIENT LICENSE LOCKED  (server unreachable or not configured)
   ═══════════════════════════════════════════════════════════════ */
function ClientLicenseLocked({ message, checkedAt, serverUrl, licenseBlocked }) {
  const [pinging, setPinging] = useState(false);
  const [retried, setRetried] = useState(false);
  const msgLower = String(message || '').toLowerCase();
  const isLicenseIssue = licenseBlocked || msgLower.indexOf('does not allow client') !== -1
    || msgLower.indexOf('client limit') !== -1
    || msgLower.indexOf('not allow connecting') !== -1;

  async function handleRetry() {
    setPinging(true);
    setRetried(false);
    await new Promise(function(r) { setTimeout(r, 1500); });
    setPinging(false);
    setRetried(true);
    /* Reload the whole page so LicenseGate re-checks */
    setTimeout(function() { window.location.reload(); }, 800);
  }

  return (
    <div style={{
      position       : 'fixed',
      inset          : 0,
      background     : 'linear-gradient(135deg, #0d1b3e 0%, #0f2252 60%, #1a3580 100%)',
      display        : 'flex',
      alignItems     : 'center',
      justifyContent : 'center',
      flexDirection  : 'column',
      fontFamily     : "'Plus Jakarta Sans', system-ui, sans-serif",
      gap            : 0,
    }}>
      {/* Status dot + icon */}
      <div style={{ marginBottom: 20, textAlign: 'center' }}>
        <div style={{ fontSize: 56, lineHeight: 1 }}>{isLicenseIssue ? '🔒' : '🔌'}</div>
        <div style={{ marginTop: 12 }}>
          <span style={{
            display        : 'inline-flex',
            alignItems     : 'center',
            gap            : 6,
            background     : 'rgba(224,49,81,0.18)',
            border         : '1px solid rgba(224,49,81,0.45)',
            borderRadius   : 20,
            padding        : '4px 14px',
            fontSize       : 12,
            fontWeight     : 700,
            color          : '#f87b93',
          }}>
            <span style={{
              width          : 7,
              height         : 7,
              borderRadius   : '50%',
              background     : '#e03151',
              display        : 'inline-block',
              animation      : isLicenseIssue ? 'none' : 'tcPulse 1.5s ease-in-out infinite',
            }} />
            {isLicenseIssue ? 'License Restriction' : 'Server Not Reachable'}
          </span>
        </div>
      </div>

      {/* Card */}
      <div style={{
        background     : '#ffffff',
        borderRadius   : 18,
        padding        : '36px 40px',
        maxWidth       : 440,
        width          : '90%',
        boxShadow      : '0 8px 40px rgba(0,0,0,0.3)',
        textAlign      : 'center',
      }}>
        <div style={{ fontSize: 20, fontWeight: 800, color: C.text, marginBottom: 8 }}>
          {isLicenseIssue ? 'Counter PC Not Allowed' : 'Cannot Connect to Server'}
        </div>
        <div style={{ fontSize: 13, color: C.muted, marginBottom: 20, lineHeight: 1.6, whiteSpace: 'pre-line' }}>
          {message || (isLicenseIssue
            ? 'This license does not allow counter PCs. Use the main server PC or upgrade your license.'
            : 'Server not reachable. Please start the main server PC.')}
        </div>
        {serverUrl && (
          <div style={{
            background     : '#f0f4ff',
            borderRadius   : 8,
            padding        : '8px 14px',
            fontSize       : 12,
            color          : C.muted,
            marginBottom   : 20,
            fontFamily     : 'monospace',
            wordBreak      : 'break-all',
          }}>
            {serverUrl}
          </div>
        )}
        <div style={{
          background   : '#fde8ed',
          border       : '1px solid #f9a8ba',
          borderRadius : 8,
          padding      : '12px 16px',
          fontSize     : 13,
          color        : C.red,
          marginBottom : 20,
          textAlign    : 'left',
        }}>
          <div style={{ fontWeight: 700, marginBottom: 4 }}>Steps to fix:</div>
          {isLicenseIssue ? (
            <>
              <div>1. On the <strong>main server PC</strong>, open Settings → Network → License Sync</div>
              <div>2. Check <strong>Allowed PCs</strong> — if it says &quot;Not Allowed&quot;, your license is single-PC only</div>
              <div>3. Contact Techon Computers to upgrade your license for counter PCs, then sync license on the main PC</div>
            </>
          ) : (
            <>
              <div>1. Turn on the main server computer</div>
              <div>2. Make sure Techon ERP is running on it</div>
              <div>3. Check that both computers are on the same network</div>
            </>
          )}
        </div>
        <button
          onClick={handleRetry}
          disabled={pinging}
          style={{
            width        : '100%',
            padding      : '12px',
            background   : pinging ? '#94a3b8' : 'linear-gradient(135deg, #2255d4, #2979ff)',
            color        : '#fff',
            border       : 'none',
            borderRadius : 10,
            fontSize     : 14,
            fontWeight   : 700,
            cursor       : pinging ? 'not-allowed' : 'pointer',
          }}
        >
          {pinging ? 'Retrying...' : retried ? '✓ Reloading...' : (isLicenseIssue ? '🔄 Check Again' : '🔄 Retry Connection')}
        </button>
        {checkedAt && (
          <div style={{ marginTop: 12, fontSize: 11, color: C.muted }}>
            Last checked: {checkedAt}
          </div>
        )}
      </div>

      {/* Contact footer */}
      <div style={{
        marginTop      : 28,
        display        : 'flex',
        flexWrap       : 'wrap',
        gap            : '6px 16px',
        justifyContent : 'center',
      }}>
        <a href="mailto:info@techon.lk"
          style={{ color: '#7eb8ff', fontSize: 12, fontWeight: 600, textDecoration: 'none' }}>
          ✉️ info@techon.lk
        </a>
        <span style={{ color: 'rgba(255,255,255,0.25)', fontSize: 12 }}>|</span>
        <span style={{ color: 'rgba(200,220,255,0.85)', fontSize: 12, fontWeight: 500 }}>
          📞 +94 701234678
        </span>
      </div>

      {/* Pulse animation keyframes */}
      <style>{`@keyframes tcPulse{0%,100%{opacity:1}50%{opacity:0.3}}`}</style>
    </div>
  );
}

