/* ═══════════════════════════════════════════════════════════════
   CLIENT STATUS STRIP  (shown at top of App for network clients)
   Adapts colour + message for: activated / trial / grace / cache
   ═══════════════════════════════════════════════════════════════ */
function ClientStatusStrip({ shopName, plan, status, checkedAt, fromCache, graceDaysLeft, cacheWarning }) {
  const isGrace   = status === 'grace';
  const isTrial   = status === 'trial';
  const isCache   = !!fromCache;
  const isWarning = isCache && !!cacheWarning; /* Tier-2: cache is 2-24h old */

  /* Colour scheme: grace > tier-2 cache warning > normal cache > trial > normal */
  let bg, border, textColor, dot, label, icon, mainMsg;

  if (isGrace) {
    bg = '#fef3e2'; border = '#fcd34d'; textColor = '#92400e'; dot = '#e07a10';
    label = 'Grace Period';
    icon = '⏰';
    mainMsg = 'Server license expired — ' + (graceDaysLeft || '?') + ' grace day' + (graceDaysLeft !== 1 ? 's' : '') + ' left';
  } else if (isWarning) {
    /* Tier-2: stale cache — amber + bolder warning */
    bg = '#fff7ed'; border = '#fdba74'; textColor = '#9a3412'; dot = '#ea580c';
    label = 'Stale Cache';
    icon = '⚠️';
    mainMsg = 'Server unreachable — license check overdue';
  } else if (isCache) {
    /* Tier-1: fresh cache — soft yellow */
    bg = '#fffbeb'; border = '#fde68a'; textColor = '#78350f'; dot = '#f59e0b';
    label = 'Cached';
    icon = '⚡';
    mainMsg = 'Using cached license — server unreachable';
  } else if (isTrial) {
    bg = '#fef3e2'; border = '#fcd34d'; textColor = '#92400e'; dot = '#e07a10';
    label = 'Trial'; icon = '🕒'; mainMsg = 'Connected to main server';
  } else {
    bg = '#e8f5ee'; border = '#86efac'; textColor = '#166534'; dot = '#0f9e6e';
    label = 'Activated'; icon = '🌐'; mainMsg = 'Connected to main server';
  }

  return (
    <div style={{
      background      : bg,
      borderBottom    : '1.5px solid ' + border,
      padding         : '5px 16px',
      display         : 'flex',
      alignItems      : 'center',
      gap             : 10,
      fontSize        : 11,
      fontFamily      : "'Plus Jakarta Sans', system-ui, sans-serif",
      flexShrink      : 0,
    }}>
      <span style={{
        width        : 7,
        height       : 7,
        borderRadius : '50%',
        background   : dot,
        display      : 'inline-block',
        flexShrink   : 0,
      }} />
      <span style={{ color: textColor, fontWeight: 700 }}>{icon} {mainMsg}</span>
      {shopName && (
        <span style={{ color: textColor, fontWeight: 500 }}>· {shopName}</span>
      )}
      {plan && (
        <span style={{ color: textColor }}>· {label} ({plan})</span>
      )}
      {checkedAt && (
        <span style={{ marginLeft: 'auto', color: textColor, opacity: 0.7, whiteSpace: 'nowrap' }}>
          Last verified: {checkedAt}
        </span>
      )}
    </div>
  );
}

