function UsageWarnBanner({ usageCounts, maxRecords, onActivate }) {
  var max  = maxRecords || 20;
  var u    = usageCounts || {};
  var sc   = u.sales     || 0;
  var pc   = u.products  || 0;
  var cc   = u.customers || 0;
  var ec   = u.expenses  || 0;
  var puc  = u.purchases || 0;
  var suc  = u.suppliers || 0;
  var qc   = u.quotations|| 0;
  var rc   = u.repairs   || 0;

  var maxUsage  = 0;
  for (var ui = 0; ui < TRIAL_COUNT_MODULES.length; ui++) {
    var uv = u[TRIAL_COUNT_MODULES[ui].key] || 0;
    if (uv > maxUsage) maxUsage = uv;
  }
  var remaining = Math.max(0, max - maxUsage);
  var pct       = Math.round((maxUsage / max) * 100);
  var isCritical = pct >= 80;
  var barColor   = pct >= 80 ? '#e03151' : pct >= 60 ? '#d97706' : '#2979ff';
  var bg         = pct >= 80
    ? 'linear-gradient(90deg,#c82040,#e03151)'
    : 'linear-gradient(90deg,#d97706,#f59e0b)';

  /* Key modules to show in banner */
  var allMods = TRIAL_COUNT_MODULES.map(function (m) {
    return { key: m.label, val: u[m.key] || 0 };
  }).filter(function (m) { return m.val > 0; });
  if (allMods.length === 0) {
    allMods = [
      { key: 'Sales', val: sc }, { key: 'Products', val: pc },
      { key: 'Customers', val: cc }, { key: 'Purchases', val: puc },
    ];
  }
  var extraUsed = 0;

  var activateBtnStyle = {
    background: '#fff', color: barColor, border: 'none',
    borderRadius: 8, padding: '7px 16px', fontWeight: 800, fontSize: 12,
    cursor: 'pointer', whiteSpace: 'nowrap', flexShrink: 0,
    animation: isCritical ? 'tcPulse 1.6s ease-in-out infinite' : 'none',
  };

  return (
    <div style={{
      background: bg, color: '#fff',
      padding: '9px 16px', display: 'flex', alignItems: 'center',
      justifyContent: 'space-between', gap: 12, flexShrink: 0,
      fontSize: 13, fontWeight: 600,
      fontFamily: "'Plus Jakarta Sans',system-ui,sans-serif",
    }}>
      <span style={{ display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap', flex: 1 }}>
        <span style={{ fontWeight: 800 }}>
          {isCritical ? '🔴' : '⚠️'} Trial {pct}% used — {maxUsage}/{max} ({remaining} remaining)
        </span>
        <span style={{
          background: 'rgba(0,0,0,0.18)', borderRadius: 6,
          padding: '2px 9px', fontSize: 11.5, fontWeight: 700,
        }}>
          {allMods.map(function(m) { return m.key + ' ' + m.val; }).join(' · ')}
          {extraUsed > 0 ? ' · +more' : ''}
        </span>
      </span>
      <div style={{ display: 'flex', gap: 7, flexShrink: 0 }}>
        <button
          onClick={function() { window.open && window.open(SUPPORT_WA, '_blank'); }}
          style={{
            background: '#25D366', color: '#fff', border: 'none',
            borderRadius: 8, padding: '7px 13px', fontWeight: 700,
            fontSize: 12, cursor: 'pointer', whiteSpace: 'nowrap',
          }}
        >💬 WhatsApp</button>
        <button onClick={onActivate} style={activateBtnStyle}>Activate Now</button>
      </div>
    </div>
  );
}
